func sortedSquares(nums []int) []int {
	l := 0
	r := len(nums)-1
	out := make([]int, len(nums))
	for i := len(nums)-1; i >= 0; i-- {
		leftSq := nums[l] * nums[l]
		rightSq := nums[r] * nums[r]
		if leftSq >= rightSq {
			out[i] = leftSq
			l++
		} else {
			out[i] = rightSq
			r--
		}
	}
	return out
}
